:root{color-scheme:light dark;--bg:#f7f8fb;--panel:#fff;--text:#253248;--muted:#617089;--line:#e0e5ee;--accent:#4f46e5;--tint:#eeedff;--button:#fff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}a:focus-visible{outline:3px solid var(--accent);outline-offset:5px;border-radius:5px}.site-error-shell{width:min(1040px,100%);min-height:100dvh;margin:auto;display:flex;flex-direction:column;padding:0 40px}header,footer{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:28px 0}header{border-bottom:1px solid var(--line)}.site-identity{display:flex;gap:10px;align-items:center;min-width:0;font-size:13px;font-weight:600}.site-identity>span{overflow-wrap:anywhere}.site-identity i{width:8px;height:8px;flex-shrink:0;border:2px solid var(--accent);border-radius:3px;transform:rotate(-12deg)}.error-label{font:9px ui-monospace,monospace;letter-spacing:.05em;color:var(--muted);white-space:nowrap}main{flex:1;width:min(560px,100%);margin:auto;text-align:center;padding:64px 0 68px}.error-symbol{display:flex;position:relative;align-items:center;justify-content:center;width:170px;height:120px;margin:0 auto 30px}.error-symbol>span{color:var(--tint);font-size:104px;line-height:1;font-weight:750;letter-spacing:-.09em}.error-symbol svg{position:absolute;width:90px;height:90px;stroke:var(--accent);stroke-width:2;stroke-linecap:round;stroke-linejoin:round;transform:rotate(-8deg)}.eyebrow{font:9px ui-monospace,monospace;letter-spacing:.1em;color:var(--muted);overflow-wrap:anywhere}h1{font-size:clamp(32px,4vw,44px);line-height:1.12;font-weight:550;letter-spacing:-.045em;margin:18px 0}.description{max-width:440px;margin:0 auto;color:var(--muted);font-size:14px;line-height:1.9}.requested-path{padding:15px 18px;margin:28px auto;max-width:440px;text-align:left;border:1px solid var(--line);border-radius:7px;background:var(--panel)}.requested-path>span{display:block;font:8px ui-monospace,monospace;color:var(--muted);letter-spacing:.1em;margin-bottom:8px}.requested-path code{display:block;font-size:12px;line-height:1.6;overflow-wrap:anywhere}.primary{display:inline-flex;align-items:center;gap:25px;padding:13px 18px;border-radius:5px;background:var(--accent);color:var(--button);font-size:12px;font-weight:600}.primary:hover{filter:brightness(1.1)}.owner-note{max-width:350px;margin:24px auto 0;color:var(--muted);font-size:11px;line-height:1.8}footer{border-top:1px solid var(--line);color:var(--muted);font-size:10px}footer strong{font-weight:600;color:var(--text)}@media(prefers-color-scheme:dark){:root{--bg:#151c28;--panel:#19212f;--text:#d6deeb;--muted:#92a3bc;--line:#2a3445;--accent:#a5b4fc;--tint:#242e49;--button:#19223e}}@media(max-width:560px){.site-error-shell{padding:0 22px}header{flex-wrap:wrap;gap:10px;padding:23px 0}.error-label{font-size:8px}main{padding:42px 0 48px}.error-symbol{margin-bottom:20px}footer{flex-wrap:wrap;gap:12px;padding:22px 0}.description{font-size:13px}}
